cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    server_name localhost;
    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=one burst=10 nodelay;

